mapper.select:
select o.id orderId, o.buyer_brand_id buyerBrandId, b.customer_id buyerUserId, b.brand_name buyerName, b.avator buyerAvatar, o.create_at createAt, o.order_status orderStatus, o.payment_status paymentStatus, o.pay_amount payAmount from physical_order o inner join brand b on o.buyer_brand_id = b.id
1=1 AND o.seller_brand_id = #{brandId}
AND (locate(#{dto.q}, o.id) > 0 or locate(#{dto.q}, b.brand_name) > 0)
AND o.order_status = #{dto.status}
order by o.create_at desc
